.tool-bar {
  height: 100%;
  background: linear-gradient(90deg, var(--interactive-accent), var(--interactive-accent-hover));
  transition: width 0.3s ease;
  border-radius: 3px;
}

.tool-count {
  width: 50px;
  text-align: right;
  font-weight: 600;
  color: var(--text-normal);
  font-size: 0.9em;
}

.no-data {
  padding: 20px;
  text-align: center;
  color: var(--text-muted);
  font-style: italic;
}

/* Quality Panel */
.quality-panel {
  grid-column: span 2;
}

.quality-panel .dashboard-panel {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
  gap: 15px;
}

.metric-box {
  background: var(--background-primary);
  border-radius: 8px;
  padding: 20px;
  text-align: center;
  border: 1px solid var(--background-modifier-border);
  transition: transform 0.2s;
}

.metric-box:hover {
  transform: translateY(-2px);
  border-color: var(--interactive-accent);
}

.metric-value-large {
  font-size: 2.5em;
  font-weight: 700;
  color: var(--interactive-accent);
  margin-bottom: 8px;
}

.metric-label-large {
  font-size: 1.1em;
  font-weight: 600;
  color: var(--text-normal);
  margin-bottom: 5px;
}

.metric-description {
  font-size: 0.85em;
  color: var(--text-muted);
}

/* Export Button */
.kyutai-dashboard > button {
  width: 100%;
  padding: 12px;
  margin-top: 10px;
}

/* Responsive */
@media (max-width: 900px) {
  .dashboard-grid {
    grid-template-columns: 1fr;
  }

  .quality-panel {
    grid-column: span 1;
  }
}

